Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (42,'tmddbs','9788965137702','서머노트 테스트','<p>그런데 ....! 말입니다..!</p><p><strike>서머노트ㅌ를 ㅅ썼습니다</strike></p><p><font color="#000000" style="background-color: rgb(255, 255, 0);">과연 적용이 될까요 ?</font></p><p><font style="background-color: rgb(156, 198, 239);" color="#4a7b8c">수정은 어떨까요 ?! 수정도 잘 될까요 ??</font></p>',to_date('22/08/01','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (101,'devcami','9791170400608','잘하려고 애쓰지 마라.','<p class="p1" style="font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal;" helvetica="" neue";="" color:="" rgb(0,="" 0,="" 0);"=""><span style="background-color: rgb(214, 239, 214);"><span style="font-size: 18px;">﻿</span><span style="font-size: 16px;"><font color="#000000">시는 내게 유독 어려웠다. 특히 학창시절 시험문제로 만난 시는 도저히 받아들이기 어려울 때가 많았다. 시인의 의도를 맞춰야 하니까. 아니 외워서 그런거라고 받아들여야 하니까.</font></span></span></p><p class="p1" style="font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal;" helvetica="" neue";="" color:="" rgb(0,="" 0,="" 0);"=""><span style="font-size: 16px; background-color: rgb(214, 239, 214);"><font color="#000000">내 느낌은 그렇지 않은데, 그냥 그렇다고 강요당하는게 참 싫었다. 그렇다고 오답처리될 것을 알면서 내 생각대로 답을 <span>체크할 용기는 나지 않았기에 강요당한 답을 써야하는 시는 어렵고 싫었다.</span></font></span></p><p class="p1" style="font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal;" helvetica="" neue";="" color:="" rgb(0,="" 0,="" 0);"=""><span style="font-size: 13px;"><br></span></p><p class="p1" style="font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: normal;" helvetica="" neue";="" color:="" rgb(0,="" 0,="" 0);"=""><span style="font-size: 13px;">몹시 더운 날 산책을 하다가 한 줄기 시원한 바람이 불어올 때 ‘그래도 걸을만 하네!’ 라며 더위에 대한 불평도, 산책을 괜히 나왔다는 후회도 잠시 거두게 되는 것처럼, 나에게 있어 시는 내가 마주한 상황을 다른 각도로 보게 도와준다. 그래서 가끔이지만 시를 읽는 것은 멈출 수가 없다.</span></p>',to_date('22/08/24','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (82,'tester4','9788956608075','존엄성이란 무엇일까.','<p>샘데샘데</p>',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (61,'honggd','9791138410724','세상에서 고양이가 사라진다면','<p>죽음을 앞둔 남자가 자신에게 소중한 기억을 없애면</p><p>생명을 연장시켜 준다는 제안을 받아들이면서 생기는 이야기이다.</p><p><br></p><p>나중에는 인생의 소중함을 깨닫는..</p><p>"인생은 가까이서 보면 비극이지만, 멀리서 보면 희극이다"</p><p><br></p><p>그리고 마지막은 세상에서 내가 사라진다면..</p><p>주인공은 하루에 하나씩 소중한 것을 잃어야 생명이 하루씩 연장된다.</p><p>무엇이 중요한지 , 우선순위를 생각하며 하나씩 하나씩 버린다.</p><p>하지만 소중하지 않은 것은 아무것도 없다.</p><p><br></p><p>점점 나에게서 소중한 것들이 없어지는 상상을 하게되고</p><p>그것들이 없으면 나도 행복하지 않음을 깨닳게된다.</p>',to_date('22/08/12','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (81,'tester3','9791160408331','트로피컬 나이트','<p>독후감샘데샘데</p>',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (83,'tester','9791130692258','내면의 나','<p>지어내기 힘드러</p>',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (84,'tester','9791130692258','생각의 생각의 생각','<p>랄랄라</p>',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (85,'tmddbs','9788934942382','두번째 독후감.','10개만 넘기자 . . .',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (86,'tmddbs','9791134838560','나의 세번째 독후감','<p>ㅈㅔ목만 간지나게</p>',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (87,'sinsa','9791191043754','세상 어디쯤에 있는가','<p>인스타에서 많이 본 광고 책ㅋ</p>',to_date('22/08/18','RR/MM/DD'),'O');
Insert into BOOKIEONANDON.DOKOO (DOKOO_NO,MEMBER_ID,ITEM_ID,TITLE,CONTENT,ENROLL_DATE,IS_OPENED) values (62,'devcami','9788954681179','첫 독후감 등록입니다 ㅎㅎ','<p>여름을 좋아한다.</p><p>특히 여름의 찬란함을 좋아한다.</p><p>눈이 부실 정도의 햇빛이나 바다에 비치는 윤슬처럼</p><p>그런 반짝임들을 사랑하는데,</p><p>반짝임들을 보고있자면 왠지 모르게 과거를 바라보는 느낌이 든다.</p><p><br></p><p>기쁨과 슬픔의 공존</p><p>남들은 찬란함이라는 단어를 어떤 것으로 정의할지 모르지만</p><p>내게 찬란함이란 그런 모순적인 반짝임이었다.</p><p>그리고 그런 반짝임이 이 책에 담겨있었다.</p><p><br></p><p>아주 잔잔한 바다를 바라보는 것 처럼 잔잔하게 흘러가고</p><p>바다의 깊이처럼 깊은 이야기지만 깊음에 공허해지기도 하는.</p><p>모래사장을 자세히 들여다보면 조개가 있고</p><p>그 조개가 발바닥을 콕콕 찌르듯</p><p>내 마음을 콕콕 찔러 아프게 하기도 하지만</p><p>주운 조개가 마냥 못나지만은 않아서 집으로 들고 오게 되는</p><p>그런 소설이었다.</p>',to_date('22/08/12','RR/MM/DD'),'O');
