Insert into BOOKIEONANDON.QNA (QNA_NO,MEMBER_ID,TITLE,CONTENT,ENROLL_DATE,STATUS) values (42,'bookie','왜 홍길동동주렁주렁을 검색하면 검색결과가 이상하게 나오나요?','안녕하세요
제가 검색창에 여러 키워드로 검색을 해봤거든요
근데 키워드 검색으로 홍길동동주렁주렁을 검색하면 홍길동동주렁주렁과 하나도 접점이 없어보이는 책들이 잔뜩나오는데 
왜 이러는거죠?
테스트로 홍길길주렁 홍길동주렁 홍길동동주렁 하면 아무것도 안나오는데
홍길동동주렁주렁만 책들이 나옵니다;;;
왜 홍길동동주렁주렁만 저러는지 알려주..렁주렁.....',to_date('22/08/23','RR/MM/DD'),'E');
Insert into BOOKIEONANDON.QNA (QNA_NO,MEMBER_ID,TITLE,CONTENT,ENROLL_DATE,STATUS) values (21,'devcami','북클럽은 가입신청 후 모집기간이 지났는데 해지할 수 있나요 ?','북클럽은 가입신청 후 모집기간이 지났는데 다른 북클럽에 가입하고싶어서요 해지할 수 있나요 ?',to_date('22/08/18','RR/MM/DD'),'U');
Insert into BOOKIEONANDON.QNA (QNA_NO,MEMBER_ID,TITLE,CONTENT,ENROLL_DATE,STATUS) values (1,'honggd','책 검색 관련 문의드립니다.','홍길동동주렁주렁을 검색하면 관련없는 책의 정보들이 수두루빽빽히 나오는데 왜 그런것인가요 ?',to_date('22/08/09','RR/MM/DD'),'E');
Insert into BOOKIEONANDON.QNA (QNA_NO,MEMBER_ID,TITLE,CONTENT,ENROLL_DATE,STATUS) values (2,'honggd','문의글을 등록','하고 나서 어디로 가나?',to_date('22/08/09','RR/MM/DD'),'E');
REM INSERTING into BOOKIEONANDON.QNA_COMMENT
SET DEFINE OFF;
Insert into BOOKIEONANDON.QNA_COMMENT (COMMENT_NO,QNA_NO,MEMBER_ID,COMMENT_CONTENT,CREATED_AT) values (41,42,'admin','안녕하세요.
알라딘 고객센터입니다.

만족하실 만한 답변드리지 못하여 송구합니다.

담당부서 확인 결과
형태소로 분석된 ''홍''과 ''길''이 모두 제목/부제/저자명 등에 포함되어 있는 상품이 검색결과에 걸리고 있습니다.
검색엔진의 키워드 분석은, 형태소 등록 유무 그리고 띄어쓰기 유무에 크게 영향을 받습니다.
- 예를 들어 ''홍길동동주렁주렁''과,
- 중간에 띄어쓰기가 포함된 ''홍길동동 주렁주렁''은, ''홍길동(명사) / 동(명사) / 주렁주렁(비명사)''으로, 그 결과가 다르게 나올 수 있습니다.

더 나은 서비스를 제공해드릴 수 있도록 노력하겠습니다.

편안한 하루 보내세요.
감사합니다.',to_date('22/08/23','RR/MM/DD'));
