Insert into BOOKIEONANDON.QNA_COMMENT (COMMENT_NO,QNA_NO,MEMBER_ID,COMMENT_CONTENT,CREATED_AT) values (2,2,'admin','답변 추가로 작성합니다.',to_date('22/08/09','RR/MM/DD'));
