--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE TRIGGER "BOOKIEONANDON"."TRIGGER_CHAT_COMMENT" 
    after 
    update on member 
    for each row 
begin 
    if updating then 
    update chat_comment set nickname = :new.nickname where nickname = :old.nickname;
    end if;
end;

